/// A proc called once per entry of `calls`, its state carried from each call to the next.
pub fn call_seq(name: &str, calls: &[Vec<f64>]) -> Option<Vec<Vec<f64>>> {
    let mut outs = Vec::new();
    match name {
        "selftest::dwell" => {
            let mut st = crate::selftest::DwellState::default();
            for x in calls {
                if x.len() != 2 { return None; }
                let mut out = Vec::new();
                let r = crate::selftest::dwell(&mut st, x[0], x[1]);
                out.push(r.0);
                out.push(r.1);
                out.push(if r.2 { 1.0 } else { 0.0 });
                out.push(r.3 as f64);
                outs.push(out);
            }
        }
        "selftest::least" => {
            let mut st = crate::selftest::LeastState::default();
            for x in calls {
                if x.len() != 1 { return None; }
                let mut out = Vec::new();
                let r = crate::selftest::least(&mut st, x[0]);
                out.push(r.0);
                out.push(if r.1 { 1.0 } else { 0.0 });
                outs.push(out);
            }
        }
        "selftest::switches" => {
            let mut st = crate::selftest::SwitchesState::default();
            for x in calls {
                if x.len() != 1 { return None; }
                let mut out = Vec::new();
                let r = crate::selftest::switches(&mut st, x[0] as i64);
                out.push(r.0 as f64);
                out.push(r.1 as f64);
                outs.push(out);
            }
        }
        "selftest::accumulate" => {
            let mut st = crate::selftest::AccumulateState::default();
            for x in calls {
                if x.len() != 2 { return None; }
                let mut out = Vec::new();
                let r = crate::selftest::accumulate(&mut st, x[0], x[1] as i64);
                out.push(r);
                outs.push(out);
            }
        }
        "selftest::noisy" => {
            let mut st = crate::selftest::NoisyState::default();
            for x in calls {
                if x.len() != 1 { return None; }
                let mut out = Vec::new();
                let r = crate::selftest::noisy(&mut st, x[0]);
                out.push(r.0);
                out.push(r.1);
                outs.push(out);
            }
        }
        _ => return None,
    }
    Some(outs)
}
